// ── PARSE DATA ──────────────────────────────────────────
var rawEl=g('kuraw');
var d={};
try{
  if(rawEl&&rawEl.value.trim()){
    var dec=document.createElement('textarea');
    dec.innerHTML=rawEl.value.trim();
    d=JSON.parse(dec.value.trim());
  }
}catch(e){}

// Look up skill from local table using id from AI
var skId=d.id||'';
var sk=SK[skId];

var TH=(d.lang==='th');
var win=g('kuwin');
if(!win)return;

// Fallback if skill not found
if(!sk){
  win.innerHTML='<div style="padding:22px;text-align:center;font-family:\'Noto Serif JP\',serif;font-size:10px;letter-spacing:2px;color:#484440;background:#07090d;border:1px solid #2a2030;border-radius:12px">SKILL NOT FOUND<br><span style="font-size:9px;opacity:.5">id: '+esc(skId||'(empty)')+'</span></div>';
  return;
}

// ── THEME ───────────────────────────────────────────────
var acc=d.charColor||'#8B6FAE';
var rgb=hexRgb(acc);
win.style.setProperty('--acc',acc);
win.style.setProperty('--acc-rgb',rgb);
win.style.setProperty('--abg','rgba('+rgb+',.13)');
win.style.setProperty('--abd','rgba('+rgb+',.32)');

var faction=(d.faction||'slayer').toLowerCase();
var FBGS={slayer:'#07090d',demon:'#100808',human:'#0f0c0a'};
var FBG2={slayer:'#0d0f18',demon:'#1a0a0a',human:'#1a1612'};
win.style.setProperty('--bg',FBGS[faction]||FBGS.slayer);
win.style.setProperty('--bg2',FBG2[faction]||FBG2.slayer);

// ── CAT LABELS ──────────────────────────────────────────
function catLabel(cat,th){
  var en={all:'Universal',slayer:'Demon Slayer',demon:'Demon',hashira:'Hashira',upper_moon:'Upper Moon'};
  var th_={all:'ทุกฝ่าย',slayer:'นักล่าอสูร',demon:'อสูร',hashira:'เสาหลัก',upper_moon:'Upper Moon'};
  return th?(th_[cat]||cat):(en[cat]||cat);
}

// ── RENDER ──────────────────────────────────────────────
function render(){
  var level=parseInt(d.level)||1;
  var maxLevel=sk.m;
  var isNew=(d.isNew!==false)&&level===1;

  var nm=TH?sk.th:sk.en;
  var nmJP=sk.jp||'';
  var nmAlt=TH?sk.en:sk.th;
  var desc=TH?sk.tD:sk.eD;
  var eff=TH?sk.tf:sk.ef;
  var wm=(sk.jp||'').charAt(0)||'刃';

  var badge=isNew?
    '<span class="ku-badge-new">'+(TH?'ใหม่':'NEW')+'</span>':
    '<span class="ku-badge-upg">'+(TH?'อัพ':'UPGRADE')+'</span>';

  var dotsH='';
  for(var i=1;i<=Math.min(maxLevel,6);i++){
    var cls=i<level?'ku-dot done':i===level?'ku-dot cur':'ku-dot';
    dotsH+='<div class="'+cls+'"></div>';
  }

  win.innerHTML=
  '<div class="ku-card">'+
    '<div class="ku-card-bg"></div>'+
    '<div class="ku-head">'+
      '<div class="ku-title">'+(TH?'✦ ปลดล็อคสกิล ✦':'✦ SKILL UNLOCKED ✦')+'</div>'+
      '<div class="ku-stars">'+
        '<div class="ku-star"></div>'+
        '<div class="ku-star"></div>'+
        '<div class="ku-star"></div>'+
      '</div>'+
    '</div>'+
    '<div class="ku-body">'+
      '<div class="ku-wm">'+esc(wm)+'</div>'+
      '<div class="ku-icon-wrap" id="ku-iw">'+
        '<div class="ku-ring3"></div>'+
        '<div class="ku-ring2"></div>'+
        '<div class="ku-ring"></div>'+
        '<div class="ku-glow"></div>'+
        '<div class="ku-ico">'+esc(sk.ico||'◆')+'</div>'+
      '</div>'+
      '<div class="ku-cat">'+esc(catLabel(sk.cat,TH))+'</div>'+
      '<div class="ku-name">'+esc(nm)+badge+'</div>'+
      (nmJP?'<div class="ku-namejp">'+esc(nmJP)+'</div>':'')+
      (nmAlt&&nmAlt!==nm?'<div class="ku-nameth">'+esc(nmAlt)+'</div>':'')+
      (maxLevel>1?
        '<div class="ku-levels">'+dotsH+
          '<span class="ku-lv-lbl">Lv '+level+' / '+maxLevel+'</span>'+
        '</div>':'')+
      (eff?
        '<div class="ku-effect">'+
          '<div class="ku-effect-ico">'+esc(sk.ico||'✦')+'</div>'+
          '<div class="ku-effect-txt">'+esc(eff)+'</div>'+
        '</div>':'')+
      (desc?'<div class="ku-desc">'+esc(desc)+'</div>':'')+
      '<div class="ku-div"></div>'+
      '<div class="ku-foot">'+
        '<div class="ku-sp-row">'+
          '<div class="ku-sp-item">'+
            '<div class="ku-sp-lbl">'+(TH?'SP ใช้':'SP Spent')+'</div>'+
            '<div class="ku-sp-val ku-sp-spent">−'+esc(d.spSpent||0)+'</div>'+
          '</div>'+
          '<div class="ku-sp-item">'+
            '<div class="ku-sp-lbl">'+(TH?'SP คงเหลือ':'Remaining')+'</div>'+
