          '</div>'+
        '</div>'+
        '<div class="ku-lng" id="kulng">'+(TH?'EN':'TH')+'</div>'+
      '</div>'+
    '</div>'+
    '<div class="ku-seal">'+esc(d.charName||'')+(d.charName?'　·　':'')+'鬼滅の刃</div>'+
  '</div>';

  // particles
  var iw=document.getElementById('ku-iw');
  if(iw){
    var pts=[0,30,60,90,120,150,180,210,240,270,300,330,15,75,135,195];
    pts.forEach(function(a,i){
      var p=document.createElement('div');
      p.className='ku-pt';
      var rad=a*Math.PI/180;
